def readable(s):
 s=re.sub(r'(?<=[A-Za-zÀ-ÿ])(?=\d)|(?<=\d)(?=[A-Za-zÀ-ÿ])',' ',s)
 s=re.sub(r'\b(de|a|e|em|entre|para|com|Somente|somente|Apenas|apenas|por|até|grupo)([A-Z])\b',r'\1 \2',s)
 return re.sub(r'([:;])(?=\S)',r'\1 ',s)
def t(x,y,s,size=18,anchor='start',color='#172b45'):return f'<text x="{x}" y="{y}" font-size="{size}" text-anchor="{anchor}" fill="{color}">{html.escape(readable(str(s)))}</text>'
def line(x1,y1,x2,y2,color='#344963',width=2,dash=''):return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" stroke-width="{width}"'+(f' stroke-dasharray="{dash}"' if dash else '')+'/>'
def rect(x,y,w,h,fill='#e8f1ff',stroke='#244e87'):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>'
def circle(x,y,rad,fill='#356cb3'):return f'<circle cx="{x}" cy="{y}" r="{rad}" fill="{fill}"/>'
def poly(points,color='#2459a6',width=4):return f'<polyline points="'+ ' '.join(f'{x},{y}' for x,y in points)+f'" fill="none" stroke="{color}" stroke-width="{width}"/>'
def axes(xmax,ymax,xlab,ylab):
 a=line(90,390,810,390)+line(90,90,90,390)+t(450,440,xlab,18,'middle')+t(90,72,ylab,18)
 for i in range(6):
  y=390-300*i/5;a+=line(90,y,810,y,'#dce3eb',1)+t(78,y+6,round(ymax*i/5,2),15,'end')
 return a

def table(headers,rows):
 w=780/len(headers);a=''
 for i,row in enumerate([headers]+rows):
  y=100+48*i
  for j,c in enumerate(row):a+=rect(60+j*w,y,w,48,'#dce9fb' if i==0 else '#fff')+t(60+j*w+w/2,y+30,c,17,'middle')
 return a

def save(n,title,alt,body):
 if n in [7,8,11,19]:
  import re
  def arrow(m):
   x1,y1,x2,y2=map(float,m.groups()[:4]);return f'<polyline points="{x1},{y1} {(x1+x2)/2},{(y1+y2)/2} {x2},{y2}" fill="none" marker-mid="url(#arrow)" '+m.group(5)+'/>'
  body=re.sub(r'<line x1="([^"]+)" y1="([^"]+)" x2="([^"]+)" y2="([^"]+)" (.*?)/>',arrow,body)
 if n==12:body=body.replace('fill="#dae7ff"','fill="#dae7ff" fill-opacity="0.4"').replace('fill="#ffdbb8"','fill="#ffdbb8" fill-opacity="0.4"')
 src=f'assets/transpetro/visuais/piloto-{n:02}.svg'
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 500" width="900" height="500" role="img" aria-labelledby="title desc"><title id="title">{html.escape(title)}</title><desc id="desc">{html.escape(alt)}</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="4" markerHeight="4" orient="auto"><path d="M0 0 L10 5 L0 10 Z" fill="#243b55"/></marker></defs><rect width="900" height="500" fill="white"/>'+t(40,38,title,23)+f'<g font-family="Arial, sans-serif">{body}'+t(40,482,'Dados hipotéticos • modelo didático • sem limite legal • figura autoral',15)+'</g></svg>'
 (R/src).write_text(svg);return src

