add(16,'incendio',V,'Inventário energético em planta simplificada','Piso6m por5m. Quatro recipientes com25kg de combustível cada, com20MJ/kg. Embalagens60kg,15MJ/kg. Modeloq=soma massa×poder calorífico/área.',a,'Considerando apenas os materiais da figura, qual energia potencial por área e qual limite de interpretação?', ['Aproximadamente96,7MJ/m²; o cálculo não classifica sozinho proteção exigida ou cenário real de incêndio.','66,7MJ/m²; embalagens não participam do inventário.','30MJ/m²; apenas as embalagens devem ser consideradas.','2.900MJ/m²; a energia total já é energia por unidade de área.','193,3MJ/m²; a área de piso deve ser contada pela metade.'],'Recipientes4×25×20=2000MJ; embalagens60×15=900MJ. Área30m². Total2900/30≈96,7MJ/m². Não se atribui classificação legal a esse dado hipotético.',{'count':4,'massEach':25,'heat1':20,'mass2':60,'heat2':15,'area':[6,5],'density':2900/30},'incendio')
