add(19,'desenvolvimento_sustentavel',V,'Balanço de água e fronteira de captação','Processo produz5t/h; capta20m³/h externamente, evapora12m³/h e descarrega8m³/h; recircula internamente100m³/h. Regime estacionário, sem outras entradas/saídas.',a,'Qual intensidade de captação externa por produção e que checagem evita somar a recirculação como água nova?', ['4m³/t;20=12+8 fecha a fronteira externa, e o fluxo100 é interno.','24m³/t; todo fluxo que entra no equipamento deve ser somado como captação externa.','20m³/t; a recirculação define a quantidade de água nova.','1,6m³/t; apenas a descarga mede a captação.','2,4m³/t; só a evaporação deve ser dividida pela produção.'],'20/5=4m³/t. No contorno externo20entram e12+8saem;100recirculam sem cruzar esse contorno como captação nova. O cálculo não demonstra qualidade do efluente ou sustentabilidade integral.',{'intake':20,'evaporation':12,'discharge':8,'recirculation':100,'production':5,'intensity':4},'matematica')
